// Creative tab tools: Claude reads the Creative inbox (files the person generated by hand in the
// isolated browser, or pasted) and places them in the file. There is deliberately no tool that opens
// the browser: that stays the person's own click in the panel.

import { z } from "zod";
import { listInbox, readInboxFile, SOCIAL_SIZES } from "./creative.js";
import { normId } from "./util.js";

export function registerCreativeTools({ server, bridge, text, fail }) {
  server.registerTool(
    "figma_creative_inbox",
    {
      description:
        "List the Creative inbox: images and videos the person generated by hand in ChatGPT or Gemini (Creative tab, isolated browser) or pasted into the panel, newest first, with name, kind, size and time. Also returns the social media sizes figma_creative_place accepts. Works without the plugin.",
      inputSchema: { limit: z.number().int().min(1).max(100).optional().describe("Default 20.") },
      annotations: { readOnlyHint: true },
    },
    async ({ limit = 20 }) => {
      try {
        const r = listInbox({ limit });
        return text({ ...r, sizes: SOCIAL_SIZES, hint: r.files.length ? undefined : "Empty. Ask the person to open ChatGPT or Gemini from the Creative tab in the plugin, generate, and download or paste the result." });
      } catch (e) {
        return fail(e);
      }
    }
  );

  server.registerTool(
    "figma_creative_place",
    {
      description:
        "Place a Creative inbox file (image or video, by name from figma_creative_inbox) in the open Figma file. With nodeIds it becomes the fill of those layers. Otherwise a new layer is made next to the selection (or inside parentId): a frame at a social size when size is given (ig-square, ig-portrait, story, linkedin-post, x-post, youtube-thumb, fb-cover), else a rectangle at the file's own size. Images: PNG, JPG or GIF up to 4096 px (WEBP only through the panel's Place button, which converts it). Videos need a paid Figma plan. Needs 'Allow edits'. One undo step.",
      inputSchema: {
        name: z.string().min(1).describe("File name exactly as figma_creative_inbox lists it."),
        nodeIds: z.array(z.string().min(1)).max(200).optional().describe("Layers to fill. Omit to create a new layer."),
        size: z.enum(Object.keys(SOCIAL_SIZES)).optional().describe("Social format for a new layer. Ignored with nodeIds."),
        parentId: z.string().optional().describe("Frame or section to create the new layer in."),
        layerName: z.string().optional().describe("Name for the new layer. Default: the file name."),
        fill: z
          .object({
            scaleMode: z.enum(["FILL", "FIT", "CROP", "TILE"]).optional(),
            mode: z.enum(["replace", "add"]).optional().describe("Replace the layer's fills (default) or add on top."),
          })
          .optional(),
      },
      annotations: { destructiveHint: true, readOnlyHint: false },
    },
    async ({ name, nodeIds, size, parentId, layerName, fill }) => {
      try {
        const f = readInboxFile(name);
        if (/\.webp$/i.test(name)) throw new Error("Figma does not take WEBP from here. Ask the person to press Place on it in the Creative tab (the panel converts it), or download it as PNG.");
        const preset = size && SOCIAL_SIZES[size].width ? { ...SOCIAL_SIZES[size] } : null;
        const r = await bridge.request(
          "place_media",
          {
            kind: f.kind,
            base64: f.bytes.toString("base64"),
            name: layerName || name,
            nodeIds: (nodeIds || []).map(normId),
            parentId: parentId ? normId(parentId) : undefined,
            size: nodeIds && nodeIds.length ? null : preset,
            fill: fill || {},
            meta: { source: "creative-inbox", file: name, placedAt: new Date().toISOString() },
          },
          120000
        );
        return text({ file: name, ...r });
      } catch (e) {
        return fail(e);
      }
    }
  );
}
